#!/usr/bin/env python3
"""
Database coverage and quality figures for the 10-plant database (brief 2026-11-02 deliverable D).

  python3 -I tools/coverage_report.py          # -> eval/coverage-<date>.md (markdown tables) and prints a summary

Per plant: live claims by source type, by status, by tier; fields with ≥1 / ≥2 independent sources; gate fields missing;
disagreements and condition-dependent variation (from brain/data/diagnosis.json); practitioner claims by completeness level;
local-evidence claims (place at the Vancouver scale). Nothing is hand-written. Standard library only.
"""
import json, os
from collections import Counter, defaultdict
from datetime import date

HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.environ.get("PLANTING_DB_ROOT") or os.path.dirname(HERE)
J = lambda p: json.load(open(os.path.join(ROOT, p), encoding="utf-8"))
SCHEMA, DIAG, REL = J("schema.json"), J("brain/data/diagnosis.json"), J("relations.json")
TIER = {f: t for t, d in SCHEMA["field_tiers"].items() for f in d.get("fields", {})}
GATE = list(SCHEMA["field_tiers"]["gate"]["fields"]); COMPARE = list(SCHEMA["field_tiers"]["compare"]["fields"]); EXT = list(SCHEMA["field_tiers"]["extended"]["fields"])
PLANTS = {f[:-5]: J(os.path.join("plants", f)) for f in sorted(os.listdir(os.path.join(ROOT, "plants"))) if f.endswith(".json")}
live = lambda c: c.get("status") != "retired" and c.get("source_type") != "model"
LOCAL = {"place:vancouver", "place:city_of_vancouver", "place:north_vancouver"}
TODAY = date.today().isoformat()
rows, field_matrix, totals = [], {}, Counter()
for pid, p in PLANTS.items():
    cs = p["claims"]; L = [c for c in cs if live(c)]
    by_type = Counter(c["source_type"] for c in L); by_status = Counter(c["status"] for c in L); by_tier = Counter(TIER.get(c["field"], "?") for c in L)
    srcs_per_field = defaultdict(set)
    for c in L: srcs_per_field[c["field"]].add(c["source_id"])
    f1 = sum(1 for f in TIER if srcs_per_field.get(f)); f2 = sum(1 for f in TIER if len(srcs_per_field.get(f, ())) >= 2)
    gate_missing = [f for f in GATE if not srcs_per_field.get(f)]
    prac = [c for c in L if c["source_type"] == "practitioner"]; levels = Counter((c.get("practitioner_meta") or {}).get("completeness") for c in prac)
    local = sum(1 for c in L if c.get("place") in LOCAL)
    P = f"plant:{pid}"
    dis = sum(1 for d in DIAG["disagreement"] if d["plant"] == P); var = sum(1 for v in DIAG["variation"] if v["plant"] == P)
    rels = [r for r in REL["relations"] if pid in (r["plant_a"], r["plant_b"]) and r.get("status") != "retired"]
    rows.append({"plant": p["entity"]["scientific_name"], "pid": pid, "type": p["entity"].get("kpu_plant_type"), "claims": len(cs), "live": len(L), "retired": sum(1 for c in cs if c.get("status") == "retired"), "sources": len({c["source_id"] for c in L}), "by_type": by_type, "by_status": by_status, "by_tier": by_tier, "f1": f1, "f2": f2, "gate_missing": gate_missing, "prac": len(prac), "levels": levels, "local": local, "dis": dis, "var": var, "rels": len(rels), "rels_sourced": sum(1 for r in rels if r["source_type"] != "model")})
    field_matrix[pid] = {f: len(srcs_per_field.get(f, ())) for f in TIER}
    totals.update({"claims": len(cs), "live": len(L), "prac": len(prac), "local": local, "dis": dis, "var": var})
nf = len(TIER)
o = [f"# Database coverage and quality · {TODAY}", "", f"Generated by `python3 -I tools/coverage_report.py` from plants/*.json, brain/data/diagnosis.json and relations.json. {len(PLANTS)} plants · {totals['claims']} claims ({totals['live']} live; retired model placeholders excluded from every figure below) · {nf} schema fields ({len(GATE)} gate · {len(COMPARE)} compare · {len(EXT)} extended).", "",
     "## Per plant", "", "| plant | KPU type | live claims | sources | practitioner (L0/L1/L2) | database | municipal | verified / unverified | fields ≥1 src | fields ≥2 src | gate missing | local-scale claims | disagreements | variation | relations (sourced) |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
for r in rows:
    lv = r["levels"]; o.append(f"| *{r['plant']}* | {r['type']} | {r['live']} | {r['sources']} | {r['prac']} ({lv.get('L0', 0)}/{lv.get('L1', 0)}/{lv.get('L2', 0)}) | {r['by_type'].get('database', 0)} | {r['by_type'].get('municipal', 0)} | {r['by_status'].get('verified', 0)} / {r['by_status'].get('unverified', 0)} | {r['f1']}/{nf} | {r['f2']}/{nf} | {', '.join(r['gate_missing']) or '—'} | {r['local']} | {r['dis']} | {r['var']} | {r['rels']} ({r['rels_sourced']}) |")
o += ["", "## Field × plant: number of independent sources (live claims)", "", "| field (tier) | " + " | ".join(r["plant"].split()[0][:4] + "." + r["plant"].split()[1][:5] for r in rows) + " |", "|---|" + "---|" * len(rows)]
for f in GATE + COMPARE + EXT:
    o.append(f"| {f} ({TIER[f][0]}) | " + " | ".join(str(field_matrix[r['pid']][f]) if field_matrix[r['pid']][f] else "·" for r in rows) + " |")
o += ["", "## Sources used", ""]
src_use = Counter(); src_plants = defaultdict(set)
for pid, p in PLANTS.items():
    for c in p["claims"]:
        if live(c): src_use[c["source_id"]] += 1; src_plants[c["source_id"]].add(pid)
S = {s["id"]: s for s in J("sources.json")["sources"]}
o += ["| source | type | tier | geo | live claims | plants |", "|---|---|---|---|---|---|"]
for sid, n in src_use.most_common():
    s = S.get(sid, {}); o.append(f"| {sid} | {s.get('type')} | {s.get('licence_tier', '—')} | {s.get('geo_specificity')} | {n} | {len(src_plants[sid])} |")
o += ["", "## Reading the quality, not the counts", "", f"- Verification: {sum(r['by_status'].get('verified', 0) for r in rows)} live claims are verified — the City of Vancouver inventory (open data, values stored directly) and the survey (the respondent's own words); every literature / database claim is **unverified** by decision D5 (Kay's unified review, checklists in `review/`). Counts of unverified claims are evidence collected, not evidence confirmed.", f"- Independence: a field with ≥ 2 sources ({sum(r['f2'] for r in rows)} plant × field cells) can show agreement or disagreement; a field with 1 source ({sum(r['f1'] - r['f2'] for r in rows)} cells) cannot be cross-checked. {totals['dis']} disagreements and {totals['var']} condition-dependent variations are recorded as data (diagnosis.json), never resolved.", f"- Locality: {totals['local']} live claims are at the Vancouver scale (City of Vancouver trees, iNaturalist Greater Vancouver, survey); the rest are BC, PNW, North America, UK or global and say so in `place`.", f"- Practitioner knowledge: {totals['prac']} claims from {len({c['source_id'] for p in PLANTS.values() for c in p['claims'] if c['source_type'] == 'practitioner'})} anonymous respondents; L0 selection reasons are stored but never cited (R2), only L1–L2 notes can be quoted.", "- Gaps are listed per plant above (gate fields with no sourced claim) and in `brain/data/kg.json gaps`; they stay empty rather than being filled by the model."]
path = os.path.join(ROOT, "eval", f"coverage-{TODAY}.md"); open(path, "w", encoding="utf-8").write("\n".join(o) + "\n")
print(f"{len(PLANTS)} plants · {totals['claims']} claims · {totals['live']} live · {totals['prac']} practitioner · {totals['local']} local · {totals['dis']} disagreements · {totals['var']} variations -> {os.path.relpath(path, ROOT)}")
for r in rows: print(f"  {r['pid']:26} live {r['live']:3} src {r['sources']:2} f≥1 {r['f1']:2} f≥2 {r['f2']:2} gate-missing {r['gate_missing']} dis {r['dis']} rel {r['rels']}")
